import{_ as t,o as a,c as o,af as d}from"./chunks/framework.B28LkSoM.js";const C=JSON.parse('{"title":"OpenCode Go 接入 CC Switch：Claude Code 原生 API 格式配置教程","description":"想用 Claude Code 又不想碰官方 API 的定价？OpenCode Go 订阅自带 Anthropic 原生格式端点，配合 CC Switch 桌面端，填一个 Base URL 加 API Key 就能把 Claude Code 切到 Go 的模型上，Qwen3.8 Max、MiniMax M3 随便切。","frontmatter":{"title":"OpenCode Go 接入 CC Switch：Claude Code 原生 API 格式配置教程","published":"2026-08-08T00:00:00.000Z","tags":["OpenCode","Claude Code","CC Switch","AI 编程","教程"],"description":"想用 Claude Code 又不想碰官方 API 的定价？OpenCode Go 订阅自带 Anthropic 原生格式端点，配合 CC Switch 桌面端，填一个 Base URL 加 API Key 就能把 Claude Code 切到 Go 的模型上，Qwen3.8 Max、MiniMax M3 随便切。","image":"https://img.tsh520.cn/file/blog/post-covers/ai-opencode-ccswitch.webp","date":"2026-08-08T00:00:00.000Z","cover":false},"headers":[],"relativePath":"posts/AI/opencode-go接入cc-switch配置教程.md","filePath":"posts/AI/opencode-go接入cc-switch配置教程.md"}'),i={name:"posts/AI/opencode-go接入cc-switch配置教程.md"};function r(n,e,c,s,p,h){return a(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1786147200000"},[...e[0]||(e[0]=[d('<blockquote><p>Claude Code 不一定要用官方 API。把 OpenCode Go 的端点接进 CC Switch，一套订阅就能让 Claude Code 跑在 Qwen3.8 Max 上。</p></blockquote><hr><h1 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h1><p>用 Claude Code 的都知道这两个坎：</p><ul><li>❌ 官方订阅要绑定国外支付，API 按 token 计费贵得肉疼</li><li>❌ 第三方中转水太深，隐私没保障，随时跑路</li></ul><p>而 OpenCode Go 订阅（首月 $5，之后 $10/月）本身就是「给你 API Key 的订阅制服务」，而且它<strong>原生提供 Anthropic 格式的端点</strong>——也就是说 Claude Code 可以直接把它当官方 API 用，不用任何格式转换。</p><p>再配合 CC Switch 这个开源桌面工具，一键切换 Provider，官方 API、Go、其他中转想用哪个用哪个。</p><hr><h1 id="一、准备工作" tabindex="-1">一、准备工作 <a class="header-anchor" href="#一、准备工作" aria-label="Permalink to &quot;一、准备工作&quot;">​</a></h1><h2 id="_1-订阅-opencode-go-并拿到-api-key" tabindex="-1">1. 订阅 OpenCode Go 并拿到 API Key <a class="header-anchor" href="#_1-订阅-opencode-go-并拿到-api-key" aria-label="Permalink to &quot;1. 订阅 OpenCode Go 并拿到 API Key&quot;">​</a></h2><p>打开控制台：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://opencode.ai/auth</span></span></code></pre></div><p>登录后订阅 Go（支持支付宝付款），然后在控制台里复制你的 <strong>API Key</strong>，先存好备用。</p><blockquote><p>还没订阅？首月 $5（≈35 元），订阅后模型随便用。可以用我的邀请链接注册，咱俩各得 $5：<a href="https://opencode.ai/go?ref=1MKPWMM7TS" target="_blank" rel="noreferrer">https://opencode.ai/go?ref=1MKPWMM7TS</a></p></blockquote><h2 id="_2-安装-cc-switch" tabindex="-1">2. 安装 CC Switch <a class="header-anchor" href="#_2-安装-cc-switch" aria-label="Permalink to &quot;2. 安装 CC Switch&quot;">​</a></h2><p>去 GitHub Releases 下载安装：</p><ul><li><a href="https://github.com/farion1231/cc-switch" target="_blank" rel="noreferrer">https://github.com/farion1231/cc-switch</a></li></ul><p>Windows 选 <code>CC-Switch-v{版本}-Windows.msi</code>，装完打开。</p><hr><h1 id="二、原理-为什么能直接接" tabindex="-1">二、原理：为什么能直接接 <a class="header-anchor" href="#二、原理-为什么能直接接" aria-label="Permalink to &quot;二、原理：为什么能直接接&quot;">​</a></h1><p>Claude Code 走的是 Anthropic 的 Messages API，而 OpenCode Go 就提供了 Anthropic 格式的端点：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Base URL:  https://opencode.ai/zen/go/v1</span></span></code></pre></div><p>走这个端点的模型（官方文档标注 <code>@ai-sdk/anthropic</code>）：</p><table tabindex="0"><thead><tr><th>模型</th><th>模型 ID</th><th>用量限制（每 5 小时）</th></tr></thead><tbody><tr><td>Qwen3.8 Max</td><td><code>qwen3.8-max</code></td><td>160 次</td></tr><tr><td>Qwen3.7 Max</td><td><code>qwen3.7-max</code></td><td>340 次</td></tr><tr><td>Qwen3.7 Plus</td><td><code>qwen3.7-plus</code></td><td>4,300 次</td></tr><tr><td>Qwen3.6 Plus</td><td><code>qwen3.6-plus</code></td><td>3,300 次</td></tr><tr><td>MiniMax M3</td><td><code>minimax-m3</code></td><td>3,200 次</td></tr><tr><td>MiniMax M2.7</td><td><code>minimax-m2.7</code></td><td>3,400 次</td></tr></tbody></table><p>所以 Claude Code 里填这个 Base URL + 你的 API Key，协议就是原生的，不需要任何中转或转换层。</p><hr><h1 id="三、cc-switch-添加-provider" tabindex="-1">三、CC Switch 添加 Provider <a class="header-anchor" href="#三、cc-switch-添加-provider" aria-label="Permalink to &quot;三、CC Switch 添加 Provider&quot;">​</a></h1><p>打开 CC Switch，点击「添加 Provider」：</p><h2 id="_1-选择工具" tabindex="-1">1. 选择工具 <a class="header-anchor" href="#_1-选择工具" aria-label="Permalink to &quot;1. 选择工具&quot;">​</a></h2><p>工具类型选 <strong>Claude Code</strong>。</p><h2 id="_2-填写配置" tabindex="-1">2. 填写配置 <a class="header-anchor" href="#_2-填写配置" aria-label="Permalink to &quot;2. 填写配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>填写内容</th></tr></thead><tbody><tr><td>名称</td><td><code>OpenCode Go</code>（随意，方便辨认就行）</td></tr><tr><td>API Key</td><td>你的 OpenCode Go API Key</td></tr><tr><td>Base URL</td><td><code>https://opencode.ai/zen/go/v1</code></td></tr><tr><td>模型</td><td><code>qwen3.8-max</code>、<code>qwen3.7-plus</code>、<code>minimax-m3</code> 等，换行分隔</td></tr><tr><td>思考模式</td><td>按需开启</td></tr></tbody></table><h2 id="_3-保存并启用" tabindex="-1">3. 保存并启用 <a class="header-anchor" href="#_3-保存并启用" aria-label="Permalink to &quot;3. 保存并启用&quot;">​</a></h2><p>保存后，在 Provider 列表里选中「OpenCode Go」，点击<strong>启用</strong>。</p><blockquote><p>💡 CC Switch 对 Claude Code 支持热切换，不用重启终端就能生效。其他工具（Codex、Gemini CLI 等）切换后需要重启终端。</p></blockquote><hr><h1 id="四、验证" tabindex="-1">四、验证 <a class="header-anchor" href="#四、验证" aria-label="Permalink to &quot;四、验证&quot;">​</a></h1><p>打开 Claude Code，输入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/status</span></span></code></pre></div><p>确认当前使用的模型和端点已经变成 OpenCode Go。再随便问一句，能正常回复就说明通了。</p><p>也可以直接 <code>/model</code> 切换列表里的模型，Qwen3.8 Max 写代码，MiniMax M3 量大管饱，按需切换。</p><hr><h1 id="五、注意事项" tabindex="-1">五、注意事项 <a class="header-anchor" href="#五、注意事项" aria-label="Permalink to &quot;五、注意事项&quot;">​</a></h1><ul><li>⚠️ <strong>DeepSeek V4 Flash 用不了原生格式</strong>：Go 的 DeepSeek 系列走的是 OpenAI 格式端点（<code>/chat/completions</code>），Claude Code 原生只认 Anthropic 格式。想用 DeepSeek 的话，需要 CC Switch 的本地代理做格式转换，属于进阶玩法，以后单独写一篇。</li><li>⚠️ <strong>API Key 别泄露</strong>：Key 在控制台里能随时查看，泄露了立刻去控制台重置。</li><li>⚠️ <strong>用量是订阅制的</strong>：Qwen3.8 Max 这类旗舰模型每 5 小时 160 次左右，日常够用；写日常小任务建议常驻 Qwen3.7 Plus（4,300 次/5 小时），完全跑不完。</li><li>✅ <strong>想回官方 API</strong>：在 CC Switch 里启用「官方登录」预设，跑一遍 Claude Code 的登录流程即可切回。</li></ul><hr><h1 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h1><p>一套 $10/月的 OpenCode Go 订阅，通过 CC Switch 接到 Claude Code 上，等于用订阅价享受了「原生 API」的体验——不碰官方计费、不用中转平台、支付宝就能付款。</p><p>订阅入口（用我的链接注册，咱俩各得 $5）：</p><p>👉 <a href="https://opencode.ai/go?ref=1MKPWMM7TS" target="_blank" rel="noreferrer">https://opencode.ai/go?ref=1MKPWMM7TS</a></p>',49)])])}const u=t(i,[["render",r]]);export{C as __pageData,u as default};
